#!/usr/bin/env node
// Reconstructed backend (generated by wcl api). Dependency-free.
// Serves the observed API contract from routes.json, with CRUD over db.json.
// Reset data: cp db.seed.json db.json
import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const DIR = path.dirname(fileURLToPath(import.meta.url));
// routes.json is regenerated by `wcl api`; routes.extra.json holds endpoints rebuilt by hand
// (e.g. form submissions that were never exercised on the original) and is never overwritten.
const load = (f) => (fs.existsSync(path.join(DIR, f)) ? JSON.parse(fs.readFileSync(path.join(DIR, f), "utf8")) : []);
const routes = [...load("routes.extra.json"), ...load("routes.json")];
const DB_FILE = process.env.DB_FILE ? path.resolve(process.env.DB_FILE) : path.join(DIR, "db.json");
let db = JSON.parse(fs.readFileSync(DB_FILE, "utf8"));
const save = () => fs.writeFileSync(DB_FILE, JSON.stringify(db, null, 2));

const compiled = routes.map((r) => ({ ...r, re: new RegExp("^" + r.path.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/:id/g, "([^/]+)") + "/?$") }));
const send = (res, status, body, type = "application/json") => {
  res.writeHead(status, { "content-type": type, "access-control-allow-origin": "*", "access-control-allow-methods": "GET,POST,PUT,PATCH,DELETE,OPTIONS", "access-control-allow-headers": "*" });
  if (status === 204) return res.end();
  res.end(type.includes("json") ? JSON.stringify(body) : String(body ?? ""));
};
const readBody = (req) => new Promise((r) => { let s = ""; req.on("data", (c) => (s += c)); req.on("end", () => { try { r(s ? JSON.parse(s) : {}); } catch { r({}); } }); });
const sameId = (row, id) => String(row.id ?? row._id ?? row.uuid) === String(id);

http.createServer(async (req, res) => {
  if (req.method === "OPTIONS") return send(res, 204, "");
  const url = new URL(req.url, "http://x");
  if (url.pathname === "/__health") return send(res, 200, { ok: true, routes: routes.length });
  const r = compiled.find((c) => c.method === req.method && c.re.test(url.pathname));
  if (!r) return send(res, 404, { error: "not reconstructed", method: req.method, path: url.pathname });
  const id = (url.pathname.match(r.re) || [])[1];
  const rows = r.collection ? (db[r.collection] ||= []) : null;
  switch (r.op) {
    case "list": {
      let out = rows;
      for (const [k, v] of url.searchParams) if (rows.length && k in rows[0]) out = out.filter((x) => String(x[k]) === v);
      return send(res, 200, r.wrapperKey ? { ...(r.fixture || {}), [r.wrapperKey]: out } : out);
    }
    case "read": { const row = rows.find((x) => sameId(x, id)); return row ? send(res, 200, row) : send(res, 404, { error: "not found" }); }
    case "create": {
      const body = await readBody(req);
      const nextId = rows.reduce((m, x) => (Number.isFinite(+x.id) ? Math.max(m, +x.id) : m), 0) + 1;
      const row = { id: nextId, ...body }; rows.push(row); save(); return send(res, 201, row);
    }
    case "update": {
      const i = rows.findIndex((x) => sameId(x, id)); if (i < 0) return send(res, 404, { error: "not found" });
      const body = await readBody(req); rows[i] = req.method === "PUT" ? { id: rows[i].id, ...body } : { ...rows[i], ...body }; save(); return send(res, 200, rows[i]);
    }
    case "delete": {
      const i = rows.findIndex((x) => sameId(x, id)); if (i < 0) return send(res, 404, { error: "not found" });
      rows.splice(i, 1); save(); return send(res, 204, "");
    }
    default: return send(res, r.status || 200, r.fixture ?? "", r.contentType || "application/json");
  }
}).listen(Number(process.env.PORT || 4010), "127.0.0.1", () => console.log(`reconstructed backend on http://127.0.0.1:${process.env.PORT || 4010} (${routes.length} routes)`));
